                                                                                                                                                                                               ('nr-hero', 'Neon Ronin: Afterglow', NULL, 'Game', 0, 'Carve a path through a drowned megacity in the year''s most electrifying open-world action RPG. Instant digital key delivery.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2144740/library_hero.jpg', '70% center', 'Steam', 'GLOBAL', 69.99, 3.25, NULL, 1, 0, 0, 0),
                                                                                                                                                                                               ('cp', 'Cyberpunk 2077', NULL, 'Game', 0, 'Cyberpunk 2077 is an open-world, action-adventure RPG set in the dark future of Night City. Redeem on Steam and start playing immediately.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1091500/library_600x900.jpg', NULL, 'Steam', 'GLOBAL', 59.99, 2.29, NULL, 0, 0, 1, 0),
                                                                                                                                                                                               ('er', 'Elden Ring', NULL, 'Game', 0, 'Rise, Tarnished, and be guided by grace to brandish the power of the Elden Ring and become an Elden Lord in the Lands Between.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1245620/library_600x900.jpg', NULL, 'Steam', 'GLOBAL', 59.99, 1.84, NULL, 0, 1, 1, 0),
                                                                                                                                                                                               ('rdr', 'Red Dead Redemption 2', NULL, 'Game', 0, 'Winner of over 175 Game of the Year Awards, RDR2 is an epic tale of honor and loyalty at the dawn of the modern age.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1174180/library_600x900.jpg', NULL, 'Xbox', 'GLOBAL', 59.99, 1.12, NULL, 0, 0, 1, 0),
                                                                                                                                                                                               ('bg3', 'Baldur''s Gate 3', NULL, 'Game', 0, 'Gather your party and return to the Forgotten Realms in a tale of fellowship and betrayal, sacrifice and survival.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1086940/library_600x900.jpg', NULL, 'Steam', 'EUROPE', 59.99, 2.71, NULL, 0, 1, 1, 0),
                                                                                                                                                                                               ('hl', 'Hogwarts Legacy', NULL, 'Game', 0, 'Experience Hogwarts in the 1800s. Your character is a student who holds the key to an ancient secret.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/990080/library_600x900.jpg', NULL, 'PS5', 'EUROPE', 69.99, 1.65, NULL, 0, 0, 1, 0),
                                                                                                                                                                                               ('gta', 'Grand Theft Auto V', 'Premium Edition', 'Edition', 0, 'Experience Rockstar Games'' critically acclaimed open world game, Grand Theft Auto V, plus Criminal Enterprise Starter Pack.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/271590/library_600x900.jpg', NULL, 'PS5', 'GLOBAL', 29.99, 0.95, 78, 0, 0, 0, 1),
                                                                                                                                                                                               ('sf', 'Starfield', NULL, 'Game', 0, 'In this next generation role-playing game set amongst the stars, create any character you want and explore with unparalleled freedom.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1716740/library_600x900.jpg', NULL, 'Xbox', 'GLOBAL', 69.99, 2.10, 54, 0, 1, 0, 1),
                                                                                                                                                                                               ('fh5', 'Forza Horizon 5', NULL, 'Game', 0, 'Lead breathtaking expeditions across the vibrant and ever-evolving open world landscapes of Mexico.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1551360/library_600x900.jpg', NULL, 'Xbox', 'EUROPE', 59.99, 1.65, 91, 0, 0, 0, 1),
                                                                                                                                                                                               ('nr', 'Neon Ronin: Afterglow', NULL, 'Game', 0, 'High-speed cyber-katana combat across rain-drenched rooftops. Verified global Steam key with instant delivery.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2144740/library_600x900.jpg', '78% center', 'Steam', 'GLOBAL', 69.99, 3.25, 37, 0, 0, 0, 1),
                                                                                                                                                                                               ('cp-pl', 'Cyberpunk 2077: Phantom Liberty', NULL, 'DLC', 0, 'Phantom Liberty is a new spy-thriller adventure for Cyberpunk 2077. Return as cyber-enhanced mercenary V in Dogtown.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2138330/library_600x900.jpg', '30% center', 'Steam', 'GLOBAL', 29.99, 1.30, NULL, 0, 0, 0, 0),
                                                                                                                                                                                               ('cp-ue', 'Cyberpunk 2077 Ultimate Edition', NULL, 'Edition', 0, 'Includes the base Cyberpunk 2077 game and the Phantom Liberty spy-thriller expansion.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1091500/library_600x900.jpg', '70% center', 'PS5', 'EUROPE', 79.99, 2.99, NULL, 0, 0, 0, 0),
                                                                                                                                                                                               ('cp-x', 'Cyberpunk 2077', NULL, 'Game', 0, 'Xbox Series X|S digital key for Cyberpunk 2077 in Night City.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1091500/library_600x900.jpg', '50% 20%', 'Xbox', 'GLOBAL', 59.99, 1.71, NULL, 0, 0, 0, 0),
