                                                                                                                                                                                               ('bg3-ps', 'Baldur''s Gate 3 Deluxe Edition', NULL, 'Edition', 0, 'Includes Baldur''s Gate 3 plus Digital Deluxe DLC pack for PS5.', 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1086940/library_600x900.jpg', '30% center', 'PS5', 'GLOBAL', 79.99, 3.60, NULL, 0, 0, 0, 0),
