DROP DATABASE IF EXISTS eneba_clone;
CREATE DATABASE eneba_clone CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE eneba_clone;

CREATE TABLE users (
                       id INT AUTO_INCREMENT PRIMARY KEY,
                       username VARCHAR(50) NOT NULL,
                       email VARCHAR(120) NOT NULL UNIQUE,
                       password_hash VARCHAR(255) NOT NULL,
                       created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE products (
                          id VARCHAR(32) PRIMARY KEY,
                          title VARCHAR(180) NOT NULL,
                          edition VARCHAR(80) NULL,
                          type ENUM('Game', 'DLC', 'Edition', 'Software', 'Gift Card') NOT NULL DEFAULT 'Game',
                          preorder TINYINT(1) NOT NULL DEFAULT 0,
                          description TEXT NOT NULL,
                          cover TEXT NOT NULL,
                          cover_position VARCHAR(40) NULL,
                          platform ENUM('Steam', 'PS5', 'Xbox', 'Switch', 'PC') NOT NULL,
                          region ENUM('GLOBAL', 'EUROPE', 'US') NOT NULL,
                          old_price DECIMAL(10,2) NOT NULL,
                          cashback DECIMAL(10,2) NULL,
                          claimed INT NULL,
                          is_hero TINYINT(1) NOT NULL DEFAULT 0,
                          is_up_next TINYINT(1) NOT NULL DEFAULT 0,
                          is_bestseller TINYINT(1) NOT NULL DEFAULT 0,
                          is_deal TINYINT(1) NOT NULL DEFAULT 0,
                          created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE sellers (
                         id INT AUTO_INCREMENT PRIMARY KEY,
                         name VARCHAR(80) NOT NULL UNIQUE,
                         rating DECIMAL(4,1) NOT NULL,
                         sales_label VARCHAR(40) NOT NULL,
                         hue INT NOT NULL DEFAULT 260
);

CREATE TABLE offers (
                        id INT AUTO_INCREMENT PRIMARY KEY,
                        product_id VARCHAR(32) NOT NULL,
                        seller_id INT NOT NULL,
                        price DECIMAL(10,2) NOT NULL,
                        stock_count INT NOT NULL DEFAULT 25,
                        FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE,
                        FOREIGN KEY (seller_id) REFERENCES sellers(id) ON DELETE CASCADE
);

CREATE TABLE orders (
                        id VARCHAR(24) PRIMARY KEY,
                        user_id INT NOT NULL,
                        total DECIMAL(10,2) NOT NULL,
                        method ENUM('card', 'apple', 'crypto') NOT NULL DEFAULT 'card',
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE order_items (
                             id INT AUTO_INCREMENT PRIMARY KEY,
                             order_id VARCHAR(24) NOT NULL,
                             product_id VARCHAR(32) NOT NULL,
                             seller_name VARCHAR(80) NOT NULL,
                             price DECIMAL(10,2) NOT NULL,
                             qty INT NOT NULL DEFAULT 1,
                             digital_keys JSON NOT NULL,
                             FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE,
                             FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE
);






